import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); int t = Integer.parseInt(br.readLine()); while (t-- > 0) { StringTokenizer st = new StringTokenizer(br.readLine()); int n = Integer.parseInt(st.nextToken()); int d = Integer.parseInt(st.nextToken()); int h = Integer.parseInt(st.nextToken()); int[] a = new int[n]; st = new StringTokenizer(br.readLine()); for (int i = 0; i < n; i++) { a[i] = Integer.parseInt(st.nextToken()); } int currentLevel = 0; boolean redAlert = false; for (int i = 0; i < n; i++) { if (a[i] > 0) { currentLevel += a[i]; } else { if (currentLevel < d) { currentLevel = 0; } else { currentLevel -= d; } } if (currentLevel > h) { redAlert = true; } } if (redAlert) { out.println("YES"); } else { out.println("NO"); } } out.flush(); out.close(); } }